import requests

# Function to query FactorDB
def query_factordb(n):
    try:
        # Send a request to FactorDB
        url = f"http://factordb.com/api?query={n}"
        response = requests.get(url)

        if response.ok:
            data = response.json()
            # Check if factorization is completed
            if data['status'] == 'FF':
                if "factors" in data:
                    factors = data["factors"]
                    prime_factors = []
                    for factor, _ in factors:
                        prime_factors.append(int(factor))
                    return prime_factors
            else:
                print("Factorization not found in FactorDB or incomplete.")
        else:
            print("Failed to connect to FactorDB.")
    except Exception as e:
        print(f"Error querying FactorDB: {e}")
    return None

# Main function to test the script
